from html.parser import HTMLParser
from pathlib import Path
import hashlib
import json
import re

class PageText(HTMLParser):
    blocks = {'p', 'li', 'h1', 'h2', 'h3', 'h4', 'tr', 'section', 'br'}

    def __init__(self):
        super().__init__()
        self.parts = []
        self.hidden = 0

    def handle_starttag(self, tag, attrs):
        if tag in {'script', 'style'}:
            self.hidden += 1
        elif tag in self.blocks and not self.hidden:
            self.parts.append('\n')

    def handle_endtag(self, tag):
        if tag in {'script', 'style'} and self.hidden:
            self.hidden -= 1
        elif tag in self.blocks and not self.hidden:
            self.parts.append('\n')

    def handle_data(self, data):
        if not self.hidden:
            self.parts.append(re.sub(r'\s+', ' ', data))

root = Path('products/services/sqlite-itch-paid-download')
sources = [('itch-payments.html', 'https://itch.io/docs/creators/payments', '26248bab355f028dbe7c73dea71e66ae6f69b33bcc954c082a63f3b91e3d1608'), ('itch-quality-guidelines.html', 'https://itch.io/docs/creators/quality-guidelines', 'f9f98212faefa057bc82ec419c4526b9c3a2bb07ff3cf16c730ac0fc88449bd9')]
terms = re.compile(r'payout|paypal|payoneer|stripe|tax interview|withhold|revenue share|processing fee|transaction fee|minimum|canada|canadian|educational|tools|generative|ai.generated|disclos', re.I)
result = []
for filename, url, expected in sources:
    raw = (root / 'raw' / filename).read_bytes()
    digest = hashlib.sha256(raw).hexdigest()
    if digest != expected:
        raise ValueError(f'Capture hash mismatch: {filename}')
    parser = PageText()
    parser.feed(raw.decode('utf-8'))
    lines = [line.strip() for line in ''.join(parser.parts).splitlines() if line.strip()]
    indices = {neighbor for index, line in enumerate(lines) if terms.search(line) for neighbor in range(max(0, index - 1), min(len(lines), index + 2))}
    result.append({'source': url, 'sha256': digest, 'excerpts': [{'line': index + 1, 'text': lines[index]} for index in sorted(indices)]})
output = root / 'official-policy-excerpts.json'
output.write_text(json.dumps(result, ensure_ascii=False, indent=2) + '\n', encoding='utf-8')
print(json.dumps([{'source': item['source'], 'excerpt_count': len(item['excerpts'])} for item in result]))
